schema_json:
{
  "$defs": {
    "BairroEntry": {
      "description": "One bairro / localidade entry with optional interview count.",
      "properties": {
        "name": {
          "description": "Bairro / localidade name, verbatim as written in the PDF.",
          "title": "Name",
          "type": "string"
        },
        "n_entrevistas": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Number of interviews allocated to this bairro, if stated. Null when not reported. For pollsters using regional structure (RJ-style with Total Região), report the per-bairro count, not the region total.",
          "title": "N Entrevistas"
        },
        "distrito": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Distrito / region the bairro belongs to, if the PDF organizes bairros by distrito (e.g., RJ-style REGIÃO/Distrito structure). Null otherwise.",
          "title": "Distrito"
        }
      },
      "required": [
        "name"
      ],
      "title": "BairroEntry",
      "type": "object"
    }
  },
  "description": "Raw bairro/localidade list from the per-poll bairro/município PDF.\n\nv2: extracts ONLY faithful facts parseable from the messy PDF layouts —\nthe bairro list (name + count + distrito), setor codes, and totals.\nCoverage class and rural inclusion are NOT inferred here (v1 did, from\nbairro name strings); they are derived downstream from matched IBGE setor\nsituacao + an electorate-coverage ratio. See docs/decisions.md.",
  "properties": {
    "pesquisa_realized": {
      "description": "True normally. False ONLY when the PDF is the 'PESQUISA NÃO REALIZADA' stamp (poll was cancelled). When false, all other fields default to empty/zero.",
      "title": "Pesquisa Realized",
      "type": "boolean"
    },
    "bairros": {
      "description": "All bairros / localidades listed in the PDF, deduplicated. HARD CAP at 50 entries (token budget). If more, populate the top 50 by n_entrevistas descending and record the true total in n_bairros_total. NEVER exceed 50. Empty list when the PDF is setor-microdata only with no bairro names.",
      "items": {
        "$ref": "#/$defs/BairroEntry"
      },
      "title": "Bairros",
      "type": "array"
    },
    "n_bairros_total": {
      "default": 0,
      "description": "Total distinct bairros listed in the PDF (may exceed len(bairros) if truncated). 0 when no bairros are listed.",
      "title": "N Bairros Total",
      "type": "integer"
    },
    "distritos_listed": {
      "description": "Distritos / regiões / administrative subdivisions if the PDF uses them (common in large munis like RJ, SP). Empty if the PDF doesn't structure by distrito.",
      "items": {
        "type": "string"
      },
      "title": "Distritos Listed",
      "type": "array"
    },
    "regional_structure": {
      "description": "True if the PDF organizes bairros by REGIÃO / Distrito (common in RJ, SP). False for flat bairro lists.",
      "title": "Regional Structure",
      "type": "boolean"
    },
    "setor_codes_sample": {
      "description": "IBGE setor censitário codes (12-15 digit numeric strings) when the PDF prints them — up to 10 examples. ALWAYS capture these when present: they key deterministic urban/rural + coverage classification downstream. Empty only when the PDF lists no setor codes. n_setores_total carries the full count.",
      "items": {
        "type": "string"
      },
      "title": "Setor Codes Sample",
      "type": "array"
    },
    "n_setores_total": {
      "default": 0,
      "description": "Total distinct setor codes in the PDF; 0 if none listed.",
      "title": "N Setores Total",
      "type": "integer"
    },
    "total_interviews_distributed": {
      "default": 0,
      "description": "Sum of n_entrevistas across all bairros if reported. 0 if interview counts are not given. Should match the poll's QT_ENTREVISTADO when fully reported.",
      "title": "Total Interviews Distributed",
      "type": "integer"
    },
    "extraction_notes": {
      "default": "",
      "description": "Free-form notes on ambiguity, format unusual, or PDF truncation. Flag here if the PDF is text-thin (likely an image-only scan that needs OCR).",
      "title": "Extraction Notes",
      "type": "string"
    }
  },
  "required": [
    "pesquisa_realized",
    "regional_structure"
  ],
  "title": "PollBairroDetail",
  "type": "object"
}
